"use strict";const path=require("path");function getRootPath(t){return(t=path.normalize(path.resolve(t)).split(path.sep)).length>0?t[0]:null}const INVALID_PATH_CHARS=/[<>:"|?*]/;function invalidWin32Path(t){const e=getRootPath(t);return t=t.replace(e,""),INVALID_PATH_CHARS.test(t)}module.exports={getRootPath:getRootPath,invalidWin32Path:invalidWin32Path};